if (root == nullptr) return;

if (item < root->data) {
    avlDelete(root->left, item);
} else if (item > root->data) {
    avlDelete(root->right, item);
} else {
    // Node with only one child or no child
    if (root->left == nullptr || root->right == nullptr) {
        TreeNode<T>* temp = root->left ? root->left : root->right;

        // No child case
        if (temp == nullptr) {
            temp = root;
            root = nullptr;
        } else { // One child case
            *root = *temp; // Copy the contents of the non-empty child
        }
        delete temp;
    } else {
        // Node with two children: get inorder successor (smallest in right subtree)
        TreeNode<T>* temp = bstFindMin(root->right);

        // Copy the inorder successor's data to this node
        root->data = temp->data;

        // Delete the inorder successor
        avlDelete(root->right, temp->data);
    }
}

// If the tree had only one node then return
if (root == nullptr) return;

root->height = std::max(bstHeight(root->left), bstHeight(root->right)) + 1;

// Balance the AVL tree
int balance = bstHeight(root->left) - bstHeight(root->right);

if (balance > 1 && item < root->left->data) {
    avlRotateRight(root);
} else if (balance < -1 && item > root->right->data) {
    avlRotateLeft(root);
} else if (balance > 1 && item > root->left->data) {
    root->left = avlRotateLeft(root->left);
    avlRotateRight(root);
} else if (balance < -1 && item < root->right->data) {
    root->right = avlRotateRight(root->right);
    avlRotateLeft(root);
}

